 51→// DetectPresence checks if Cursor is configured in the repository.
 52→func (c *CursorAgent) DetectPresence(ctx context.Context) (bool, error) {
 53→	worktreeRoot, err := paths.WorktreeRoot(ctx)
 54→	if err != nil {
 55→		worktreeRoot = "."
 56→	}
 57→
 58→	cursorDir := filepath.Join(worktreeRoot, ".cursor")
 59→	if _, err := os.Stat(cursorDir); err == nil {
 60→		return true, nil
 61→	}
 62→	return false, nil
 63→}
