 70→// ResolveSessionFile returns the path to a Cursor session file.
 71→// Cursor IDE uses a nested layout: <dir>/<id>/<id>.jsonl
 72→// Cursor CLI uses a flat layout: <dir>/<id>.jsonl
 73→// We prefer nested if the file OR directory exists (the directory may be created
 74→// before the file is flushed), otherwise fall back to flat.
 75→func (c *CursorAgent) ResolveSessionFile(sessionDir, agentSessionID string) string {
 76→	nestedDir := filepath.Join(sessionDir, agentSessionID)
 77→	nested := filepath.Join(nestedDir, agentSessionID+".jsonl")
 78→	if _, err := os.Stat(nested); err == nil {
 79→		return nested
 80→	}
 81→	// IDE creates the directory before the transcript file — predict nested path.
 82→	if info, err := os.Stat(nestedDir); err == nil && info.IsDir() {
 83→		return nested
 84→	}
 85→	return filepath.Join(sessionDir, agentSessionID+".jsonl")
 86→}
 87→
 88→// ProtectedDirs returns directories that Cursor uses for config/state.
 89→func (c *CursorAgent) ProtectedDirs() []string { return []string{".cursor"} }
 90→
 91→// GetSessionDir returns the directory where Cursor stores session transcripts.
 92→func (c *CursorAgent) GetSessionDir(repoPath string) (string, error) {
 93→	if override := os.Getenv("ENTIRE_TEST_CURSOR_PROJECT_DIR"); override != "" {
 94→		return override, nil
 95→	}
 96→
 97→	homeDir, err := os.UserHomeDir()
 98→	if err != nil {
 99→		return "", fmt.Errorf("failed to get home directory: %w", err)
100→	}
101→
102→	projectDir := sanitizePathForCursor(repoPath)
103→	return filepath.Join(homeDir, ".cursor", "projects", projectDir, "agent-transcripts"), nil
104→}
