154→// FormatResumeCommand returns an instruction to resume a Cursor session.
155→// Cursor is a GUI IDE, so there's no CLI command to resume a session directly.
156→func (c *CursorAgent) FormatResumeCommand(_ string) string {
157→	return "Open this project in Cursor to continue the session."
158→}
